import torch as t


def solve(n, k, lo, hi, col):
    """A column partitioned between two out= writes."""
    canvas = t.zeros((n, 2))
    t.arange(k, out=canvas[:k, col])
    if n - k > 0:
        t.linspace(lo, hi, n - k, out=canvas[k:, col])
    return canvas.tolist()


